from pybricks.parameters import Direction, Port
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase
from pybricks.tools import wait

from Team_Phoenix_Library import phoenix_gyro_spin_turn_the_old_way, phoenix_gyro_turn

# Set up.
right_drive = Motor(Port.F, Direction.CLOCKWISE)
left_drive = Motor(Port.B, Direction.COUNTERCLOCKWISE)
right_attachment = Motor(Port.E, Direction.CLOCKWISE)
drive_base = DriveBase(left_drive, right_drive, 62.4, 90)
left_attachment = Motor(Port.C, Direction.COUNTERCLOCKWISE)


# The main program starts here.
drive_base.straight(510)
phoenix_gyro_spin_turn_the_old_way(100, -45, 40, -45, 'left', drive_base, left_drive, right_drive)
drive_base.straight(200)
phoenix_gyro_spin_turn_the_old_way(100, 45, 30, 45, 'right', drive_base, left_drive, right_drive)
phoenix_gyro_spin_turn_the_old_way(100, 42, 30, 42, 'right', drive_base, left_drive, right_drive)
drive_base.straight(135)
drive_base.drive(200, 0)
wait(1000)
drive_base.hold()
drive_base.straight(-135)
phoenix_gyro_spin_turn_the_old_way(100, -42, 30, -42, 'left', drive_base, left_drive, right_drive)
drive_base.straight(-100)
phoenix_gyro_spin_turn_the_old_way(100, -45, 30, -45, 'left', drive_base, left_drive, right_drive)
drive_base.straight(-200)
phoenix_gyro_spin_turn_the_old_way(100, 45, 40, 45, 'right', drive_base, left_drive, right_drive)
drive_base.straight(-510)
